fw_bold mb_2">LLM Judge</h3><p class="fs_sm c_rgba(255,255,255,0.4) lh_relaxed">An AI critic evaluates each asset against the persona&#39;s taste profile for alignment.</p></div></div><div class="mt_20 p_8 bdr_2xl bg_#111 bd_1px_solid_rgba(255,255,255,0.05)"><div class="d_flex ai_center gap_2 flex-d_column ta_center mb_8"><h3 class="ff_heading fs_2xl fw_bold">Architecture</h3><p class="fs_sm c_rgba(255,255,255,0.4)">Persona → QD Engine → Assets</p></div><div class="d_grid grid-tc_repeat(5,_minmax(0,_1fr)) gap_4 ta_center ai_center"><div class="p_4 bdr_xl bg_rgba(255,255,255,0.05) bd_1px_solid_rgba(255,255,255,0.05)"><div class="fs_2xl mb_2">👤</div><div class="fs_sm fw_medium">Persona</div><div class="fs_xs c_rgba(255,255,255,0.3) mt_1">Cultural DNA</div></div><div class="c_rgba(255,255,255,0.2) fs_2xl">→</div><div class="p_4 bdr_xl bg_rgba(255,255,255,0.05) bd_1px_solid_rgba(255,255,255,0.05)"><div class="fs_2xl mb_2">🧬</div><div class="fs_sm fw_medium">QD Engine</div><div class="fs_xs c_rgba(255,255,255,0.3) mt_1">MAP-Elites</div></div><div class="c_rgba(255,255,255,0.2) fs_2xl">→</div><div class="p_4 bdr_xl bg-grad_to-br grad-from_rgba(249,115,22,0.1) grad-to_rgba(217,119,6,0.1) bd_1px_solid_rgba(249,115,22,0.2)"><div class="fs_2xl mb_2">🎨</div><div class="fs_sm fw_medium">Assets</div><div class="fs_xs c_rgba(249,115,22,0.6) mt_1">SVG · Image · Video</div></div></div></div></div></section><!--/qv--><!--qv q:id=c q:key=EMMT:lG_5--><section id="installation" class="py_32 pos_relative" q:key="nb_5"><div class="pos_absolute inset_0 bg-grad_to-b grad-from_transparent grad-via_rgba(249,115,22,0.05) grad-to_transparent"></div><div class="pos_relative max-w_4xl mx_auto px_6"><div class="d_flex ai_center gap_4 flex-d_column ta_center mb_16"><h2 class="ff_heading fs_3xl md:fs_4xl lg:fs_5xl fw_bold">Get Started</h2><p class="fs_lg c_text-muted">Install Baste and generate your first persona-driven assets.</p></div><div class="d_flex ai_stretch gap_8 flex-d_column"><div class=