er jc_center fs_sm fw_bold c_orange.400">3</div><span class="fw_semibold">Generate your first assets</span></div><div class="p_6 ff_mono fs_sm"><div class="d_flex ai_center gap_2 c_rgba(255,255,255,0.3) fs_xs mb_2">bash</div><pre class="white-space_pre-wrap wb_break-word lh_relaxed"><div q:key="0"><span q:key="nb_3"><span class="c_success">baste</span> <span class="c_text">generate cyberbotanist --dry-run</span></span></div><div q:key="1"><span class="c_text"></span></div><div q:key="2"><span q:key="nb_3"><span class="c_success">baste</span> <span class="c_text">generate cyberbotanist</span></span></div><div q:key="3"><span class="c_text"></span></div><div q:key="4"><span q:key="nb_3"><span class="c_success">baste</span> <span class="c_text">tokens cyberbotanist --format css</span></span></div></pre></div></div><div class="bdr_2xl bg_#111 bd_1px_solid_rgba(255,255,255,0.05) ov_hidden" q:key="4"><div class="d_flex ai_center gap_3 flex-d_row px_6 py_4 bd-b_1px_solid_rgba(255,255,255,0.05)"><div class="w_8 h_8 bdr_lg bg_rgba(249,115,22,0.2) d_flex ai_center jc_center fs_sm fw_bold c_orange.400">4</div><span class="fw_semibold">Use as a library</span></div><div class="p_6 ff_mono fs_sm"><div class="d_flex ai_center gap_2 c_rgba(255,255,255,0.3) fs_xs mb_2">TypeScript</div><pre class="white-space_pre-wrap wb_break-word lh_relaxed"><div q:key="0"><span q:key="nb_0"><span class="c_purple.400">import</span> <span class="c_text">{</span> <span class="c_text">getPersona, generateUIKit</span> <span class="c_purple.400">from</span> <span class="c_amber.400">&quot;baste&quot;</span><span class="c_text">;</span></span></div><div q:key="1"><span class="c_text"></span></div><div q:key="2"><span q:key="nb_0"><span class="c_purple.400">import</span> <span class="c_text">{</span> <span class="c_text">getPersona, generateUIKit</span> <span class="c_purple.400">from</span> <span class="c_amber.400">&quot;baste&quot;</span><span class="c_text">;</span></span></div><div q:key="3"><span q: