import type { Product } from "./types";
import { GatewayError } from "./errors";
import { parseProductId } from "@notorganic/contracts";

/** Explicit development approvals retain the exact scheme, host and port. */
export function parsePublicClientProductCatalog(
  configured: Record<string, string>,
): Record<string, Product> {
  return Object.fromEntries(Object.entries(configured).map(([clientId, product]) => {
    let client: URL;
    try {
      client = new URL(clientId);
    } catch (error) {
      throw new Error(`PUBLIC_CLIENT_PRODUCT_CATALOG contains an invalid client id: ${clientId}`, { cause: error });
    }
    const loopback = client.protocol === "http:" &&
      ["localhost", "127.0.0.1", "[::1]"].includes(client.hostname);
    if (!(client.protocol === "https:" || loopback) || client.origin !== clientId || client.username || client.password || client.hostname.includes("*")) {
      throw new Error(`PUBLIC_CLIENT_PRODUCT_CATALOG keys must be exact HTTPS or loopback HTTP origins: ${clientId}`);
    }
    return [clientId, parseProductId(product)];
  }));
}

/** Production integrations are operator-approved; cosmetic product hints never grant access. */
export function approvedPublicClientProduct(clientId: string, configured: Record<string, Product> = {}): Product {
  const firstParty: Record<string, Product> = {
    "https://keating.help": "keating", "https://keating.help/mobile": "keating",
    "https://twyne.love": "twyne", "https://www.twyne.love": "twyne",
    "https://interleave.love": "interleave", "https://stich.cc": "stich",
  };
  const product = configured[clientId] ?? firstParty[clientId];
  if (product) return product;
  // Existing Keating desktop clients use a dynamically allocated loopback port.
  try {
    const url = new URL(clientId);
    if (url.protocol === "http:" && ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname) && url.origin === clientId && !url.username && !url.password) return "keating";
  } catch { /* Invalid clients are rejected below. */ }
  throw new GatewayError(403, "permission_error", "This app needs Not Organic integration approval before it can sign in users. Apply at https://notorganic.info/integrate.", "integration_not_approved");
}

