export const PRODUCTS = ["notorganic", "keating", "twyne", "interleave", "stich"] as const;
export type Product = typeof PRODUCTS[number];
export type Theme = "light" | "dark";
export type Appearance = { product: Product; theme: Theme };
export const PRODUCT_NAMES: Record<Product, string> = { notorganic: "Not Organic", keating: "Keating", twyne: "Twyne", interleave: "Interleave", stich: "Stich" };
const HOSTS: Record<string, Product> = { "notorganic.info": "notorganic", "keating.help": "keating", "twyne.love": "twyne", "interleave.love": "interleave", "stich.cc": "stich" };
const isProduct = (value: unknown): value is Product => PRODUCTS.includes(value as Product);
const isTheme = (value: unknown): value is Theme => value === "light" || value === "dark";
export const APPEARANCE_COOKIE = "notorganic_appearance";

/** Cosmetic preferences only. Never use these values for authorization or redirects. */
export function resolveAppearance(search: string, cookie: string, referrer: string, systemDark: boolean): Appearance {
  const params = new URLSearchParams(search);
  let saved: string[] = [];
  try { saved = decodeURIComponent(cookie.split(";").map(v => v.trim()).find(v => v.startsWith(`${APPEARANCE_COOKIE}=`))?.slice(APPEARANCE_COOKIE.length + 1) ?? "").split(":"); } catch { /* Ignore malformed preference cookies. */ }
  let originProduct: Product | undefined;
  try { originProduct = HOSTS[new URL(referrer).hostname.replace(/^www\./, "")]; } catch { /* Direct navigation has no referrer. */ }
  const requested = params.get("product");
  const product = isProduct(requested) ? requested : originProduct ?? (isProduct(saved[0]) ? saved[0] : "notorganic");
  const requestedTheme = params.get("theme");
  const theme = isTheme(requestedTheme) ? requestedTheme : saved[0] === product && isTheme(saved[1]) ? saved[1] : systemDark ? "dark" : "light";
  return { product, theme };
}

export function applyAppearance(appearance: Appearance): void {
  document.documentElement.dataset.product = appearance.product;
  document.documentElement.dataset.theme = appearance.theme;
  document.documentElement.style.colorScheme = appearance.theme;
  const sharedDomain = location.hostname === "notorganic.info" || location.hostname.endsWith(".notorganic.info") ? "; Domain=notorganic.info" : "";
  document.cookie = `${APPEARANCE_COOKIE}=${appearance.product}:${appearance.theme}; Path=/; Max-Age=2592000; SameSite=Lax${location.protocol === "https:" ? "; Secure" : ""}${sharedDomain}`;
}

export function initializeAppearance(): Appearance {
  const value = resolveAppearance(location.search, document.cookie, document.referrer, matchMedia("(prefers-color-scheme: dark)").matches);
  applyAppearance(value);
  return value;
}

