/** Server-rendered consent: works without JavaScript under the portal's self-only CSP. */
const permissionCopy: Record<string, readonly [string, string]> = {
  "wallet:read": ["View your credit balance", "See the credits available in your account."],
  "usage:read": ["View your usage", "Read your account's usage history."],
  "billing:checkout": ["Open credit checkout", "Start a checkout for more credits."],
  "infer:fast": ["Use fast AI models", "Send requests using your account credits."],
  "infer:balanced": ["Use balanced AI models", "Send requests using your account credits."],
  "infer:reasoning": ["Use reasoning models", "Send reasoning requests using your account credits."],
  "infer:vision": ["Process images", "Send images to AI models using your account credits."],
  "infer:embedding": ["Create embeddings", "Represent content for search using your account credits."],
  "infer:image": ["Generate images", "Create images using your account credits."],
  "infer:audio": ["Process audio", "Use audio models with your account credits."],
  "realtime:connect": ["Start live AI sessions", "Connect to real-time AI conversations."],
  "tabular:predict": ["Adapt from learning results", "Send numeric learning records to TabPFN for predictions using your account credits."],
  "sync:key:read": ["Access your sync key", "Unlock your encrypted account data on this device."],
  "evolution:read": ["Read learning adaptations", "View your account's saved learning adaptations."],
  "evolution:write": ["Save learning adaptations", "Update your account's learning adaptations."],
  "evolution:execute": ["Run learning adaptations", "Execute account learning jobs."],
};

function escapeHtml(value: string): string {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;");
}

export function authorizationPage(input: { clientOrigin: string; scopes: readonly string[]; csrfToken: string; query: string }): string {
  const permissions = input.scopes.map((scope) => {
    const [label, description] = permissionCopy[scope] ?? [scope, "Access this account permission."];
    return `<li><strong>${escapeHtml(label)}</strong><span>${escapeHtml(description)}</span></li>`;
  }).join("");
  return `<!doctype html>
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>Approve connection · Not Organic</title>
<link rel="stylesheet" href="/authorization.css">
</head><body>
<main class="authorization">
  <a class="wordmark" href="/" aria-label="Not Organic account home"><img src="/brand/notorganic.png" width="36" height="36" alt="">Not Organic</a>
  <section class="consent" aria-labelledby="consent-title">
    <header><h1 id="consent-title">Allow this connection?</h1><p class="intro">An app wants to use your Not Organic account.</p></header>
    <div class="requesting-app"><span>Requesting app</span><strong>${escapeHtml(input.clientOrigin)}</strong></div>
    <h2>This app will be able to</h2>
    <ul class="permissions">${permissions}</ul>
    <details><summary>Technical permissions</summary><ul class="scope-list">${input.scopes.map((scope) => `<li><code>${escapeHtml(scope)}</code></li>`).join("")}</ul></details>
    <p class="access-note">This app can stay connected on this device for up to 30 days. Approve only if you recognize the app above.</p>
    <form method="post" action="/authorize">
      <input type="hidden" name="request" value="${Buffer.from(input.query).toString("base64url")}">
      <input type="hidden" name="csrf" value="${escapeHtml(input.csrfToken)}">
      <button class="secondary" type="submit" name="decision" value="deny">Deny access</button>
      <button class="primary" type="submit" name="decision" value="approve">Approve access</button>
    </form>
  </section>
  <p class="footer-note">Your account connection is managed by Not Organic.</p>
</main></body></html>`;
}

// Use the portal's existing palette and font stacks. Served as a stylesheet
// rather than an inline style so the existing Content-Security-Policy holds.
export const authorizationStyles = `
:root {
  color-scheme: light;
  --page: #eef0e4; --panel: #f7f8f0; --ink: #102519;
  --ink-soft: #3f5849; --forest: #103720; --forest-deep: #082718;
