  font-family: "Avenir Next", Avenir, "Segoe UI", ui-sans-serif, system-ui, sans-serif;
  color: var(--ink); background: var(--page); font-synthesis: none;
}
* { box-sizing: border-box; }
body { margin: 0; }
.authorization { width: min(100% - 32px, 600px); margin: 40px auto; }
.wordmark { display: inline-flex; align-items: center; gap: 10px; margin-bottom: 24px; color: var(--forest); text-decoration: none; font-size: 18px; font-weight: 750; }
.wordmark img { object-fit: contain; }
.consent { padding: 32px; background: var(--panel); border: 1px solid var(--line); border-radius: 16px; }
h1 { margin: 0; font-size: 30px; line-height: 1.2; letter-spacing: -.025em; font-weight: 750; text-wrap: balance; }
.intro { margin: 10px 0 24px; color: var(--ink-soft); line-height: 1.5; }
.requesting-app { padding: 16px; margin-bottom: 24px; background: var(--sunk); border-radius: 10px; }
.requesting-app span { display: block; font-size: 13px; color: var(--ink-soft); margin-bottom: 5px; }
.requesting-app strong { display: block; font-size: 17px; line-height: 1.4; overflow-wrap: anywhere; }
h2 { font-size: 16px; margin: 0 0 4px; }
.permissions { list-style: none; padding: 0; margin: 0; }
.permissions li { padding: 13px 0; border-bottom: 1px solid var(--line); }
.permissions li:last-child { border-bottom: 0; }
.permissions strong { display: block; font-size: 15px; line-height: 1.4; font-weight: 650; }
.permissions span { display: block; color: var(--ink-soft); font-size: 14px; line-height: 1.5; margin-top: 2px; }
details { margin: 12px 0 20px; font-size: 13px; }
summary { cursor: pointer; color: var(--ink-soft); padding: 7px 0; }
.scope-list { padding-left: 20px; line-height: 1.8; overflow-wrap: anywhere; }
.access-note { margin: 0 0 24px; color: var(--ink-soft); font-size: 13px; line-height: 1.6; max-width: 62ch; }
form { display: flex; gap: 12px; }
button { flex: 1; min-height: 48px; padding: 12px 16px; border: 1px solid var(--forest); border-radius: 10px; font: inherit; font-size: 15px; font-weight: 650; cursor: pointer; transition: background-color 150ms ease-out, transform 150ms ease-out; }
.primary { background: var(--forest); color: var(--panel); }
.primary:hover { background: var(--forest-deep); }
.secondary { background: transparent; color: var(--forest); }
.secondary:hover { background: var(--sunk); }
button:active { transform: translateY(1px); }
:focus-visible { outline: 3px solid var(--forest); outline-offset: 4px; }
.footer-note { color: var(--ink-soft); font-size: 12px; line-height: 1.5; text-align: center; margin: 18px 16px; }
@media (max-width: 420px) {
  .authorization { margin: 24px auto; }
  .consent { padding: 24px 20px; }
  h1 { font-size: 26px; }
  form { flex-direction: column-reverse; }
  button { width: 100%; }
}
@media (prefers-reduced-motion: reduce) { button { transition: none; } button:active { transform: none; } }
`;

