import type { ProductId } from "@notorganic/contracts";

/**
 * Visual identity for one product, expressed in the subset of CSS that email
 * clients agree on.
 *
 * Two constraints shape every field here:
 *
 * 1. Web fonts do not load in Outlook, and load unreliably elsewhere, so every
 *    `*Font` value is a stack of families that ship with the OS. The stacks are
 *    chosen so the *flavour* of each brand survives the fallback: Twyne stays
 *    a transitional serif, Keating stays monospaced, Stich stays a heavy
 *    grotesque.
 * 2. Images are blocked by default in most clients. `accent`, `mastheadFill`
 *    and `texture` therefore have to carry recognition on their own, with the
 *    logo in `markUrl` treated as an enhancement rather than the identity.
 */
export type ProductTheme = {
  id: ProductId;
  /** Display name as it appears in a sentence. */
  name: string;
  /** One line, used under the masthead. Present tense, no marketing verbs. */
  tagline: string;
  /** Canonical https origin, without a trailing slash. */
  url: string;
  /** Bare host, for link text where a full URL would wrap badly. */
  host: string;
  /** 128x128 transparent PNG served from the marketing site. */
  markUrl: string;

  /** Page background, outside the card. */
  page: string;
  /** Card background. Body copy sits on this. */
  surface: string;
  /** Inset blocks: fact tables, quotes, survey rows. */
  surfaceMuted: string;
  /** Body text. Must reach 4.5:1 on `surface`. */
  ink: string;
  /** Secondary text: labels, footnotes. Must reach 4.5:1 on `surface`. */
  inkMuted: string;
  /** Hairlines and table rules. */
  rule: string;

  /** Brand primary. Used for the masthead fill and the primary button. */
  accent: string;
