  /** Text placed on `accent`. Must reach 4.5:1 against it. */
  onAccent: string;
  /** A tint of `accent` light enough to carry `ink` at 4.5:1. */
  accentSoft: string;
  /** Text-safe accent for links on `surface`. Must reach 4.5:1. */
  accentText: string;

  /** Headings. */
  displayFont: string;
  /** Body copy. */
  bodyFont: string;
  /** Eyebrows, labels, data. */
  monoFont: string;
  /** Letter-spacing applied to headings, in em. Stich and Keating run wide. */
  displayTracking: string;
  /** Whether small labels are uppercased. */
  labelTransform: "uppercase" | "none";

  /** Corner radius for cards and inset blocks, in px. */
  radius: number;
  /** Corner radius for buttons, in px. Stich uses a full LCARS barrel. */
  buttonRadius: number;
  /**
   * The brand's texture, as a repeating gradient layered over `accent`.
   * Clients that drop it fall back to the flat `accent` underneath, so this is
   * always additive.
   */
  texture: string;
};

/**
 * Where the brand marks are served from.
 *
 * Overridable so a preview or a staging send resolves real logos instead of
 * four broken-image boxes — which is the difference between reviewing a design
 * and guessing at one. Production needs no override.
 */
const NOT_ORGANIC_MARK = (
  (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env
    ?.NOTORGANIC_BRAND_BASE ?? "https://notorganic.info/brand"
).replace(/\/$/, "");

/**
 * Where voxq is served from.
 *
 * Unlike the other products, voxq has no domain of its own yet. The default
 * below is a subdomain of infrastructure we already run, so the link resolves
 * to something we control rather than to a guess at a third party. Point
 * `VOXQ_SITE_BASE` at the real host the day one exists; nothing else in the
 * theme has to change.
 */
const VOXQ_SITE = (
  (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env
    ?.VOXQ_SITE_BASE ?? "https://voxq.notorganic.info"
).replace(/\/$/, "");

/**
 * Not Organic is the merchant of record for all four products, so its identity
 * appears in every footer even when the masthead belongs to a product.
 */
export const notorganic: ProductTheme = {
  id: "notorganic",
  name: "Not Organic",
  tagline: "One account across Twyne, Keating, Interleave, and Stich.",
  url: "https://notorganic.info",
"}

