from pathlib import Path
import difflib

root = Path('/home/diogenes/Projects/notorganic-provider')
out = Path('/home/diogenes/Projects/baste/ops')
out.mkdir(exist_ok=True)
changes = {}
def edit(path, before, after):
    original, value = changes.get(path, (None, None))
    if original is None:
        original = value = (root / path).read_text()
    if before not in value:
        raise RuntimeError('Missing context: ' + path)
    changes[path] = (original, value.replace(before, after, 1))

