  baste_credit_50: { product: "baste", priceUsd: 50, creditMicrousd: 50_000_000 },''')

patch = ''.join(''.join(difflib.unified_diff(a.splitlines(True), b.splitlines(True), fromfile='a/'+path, tofile='b/'+path)) for path, (a, b) in changes.items())
(out / 'notorganic-provider.patch').write_text(patch)
