import { approvedPublicClientProduct } from "./public-client-product";
import {
  calculateJwkThumbprint,
  decodeJwt,
  decodeProtectedHeader,
  importJWK,
  jwtVerify,
  SignJWT,
  type JWK,
} from "jose";
import { ZodError } from "zod";
import {
  ACCESS_TOKEN_TYPE,
  AccessTokenClaimsSchema,
  SignedAssertionClaimsSchema,
  type Capability,
} from "@notorganic/contracts";
import { GatewayError } from "./errors";
import {
  FIRST_PARTY_PRODUCTS,
  type CapabilityClaims,
  type GatewayConfig,
  type Product,
  type ProductAssertionClaims,
  type VerifiedPrincipal,
} from "./types";

const ASSERTION_TTL_SECONDS = 60;
const CAPABILITY_TTL_SECONDS = 5 * 60;
const DPOP_CLOCK_SKEW_SECONDS = 60;
const DEVICE_SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1_000;
const DEVICE_TOKEN_PREFIX = "nou_ds_";

function isProduct(value: unknown): value is Product {
  return (
    typeof value === "string" &&
    FIRST_PARTY_PRODUCTS.includes(value as Product)
  );
}

function scopes(value: string | undefined): Set<string> {
  return new Set((value ?? "").split(/\s+/).filter(Boolean));
}

function isPublicDpopJwk(jwk: JWK): boolean {
  return ["EC", "RSA", "OKP"].includes(jwk.kty ?? "") && jwk.d === undefined;
}

async function sha256Base64url(value: string): Promise<string> {
  return Buffer.from(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value))).toString("base64url");
}

function randomBase64url(bytes = 32): string {
  return Buffer.from(crypto.getRandomValues(new Uint8Array(bytes))).toString("base64url");
}

function newDeviceCredential(sessionId: string = crypto.randomUUID()): { sessionId: string; token: string } {
  return { sessionId, token: `${DEVICE_TOKEN_PREFIX}${sessionId}.${randomBase64url()}` };
}

function deviceSessionId(token: string): string | null {
  if (!token.startsWith(DEVICE_TOKEN_PREFIX) || token.length > 512) return null;
  const separator = token.indexOf(".", DEVICE_TOKEN_PREFIX.length);
  if (separator === -1) return null;
  const sessionId = token.slice(DEVICE_TOKEN_PREFIX.length, separator);
  const secret = token.slice(separator + 1);
  return /^[0-9a-f-]{36}$/i.test(sessionId) && /^[A-Za-z0-9_-]{43}$/.test(secret) ? sessionId : null;
}

function constantTimeEqual(left: string, right: string): boolean {
  if (left.length !== right.length) return false;
  let difference = 0;
  for (let index = 0; index < left.length; index += 1) difference |= left.charCodeAt(index) ^ right.charCodeAt(index);
  return difference === 0;
}

export interface PublicCapabilityResponse {
  access_token: string;
  token_type: "DPoP";
  expires_in: 300;

